//===----------------------------------------------------------------------===//
//Localconstantpropagation.
//

///Ifaterminatorinstructionispredicatedonaconstantvalue,convertit
///intoanunconditionalbranchtotheconstantdestination.
///Thisisanontrivialoperationbecausethesuccessorsofthisbasicblock
///musthavetheirPHInodesupdated.
///AlsocallsRecursivelyDeleteTriviallyDeadInstructions()onanybranch/switch
///conditionsandindirectbraddressesthismightmakedeadif
///DeleteDeadConditionsistrue.
boolConstantFoldTerminator(BasicBlock*BB,boolDeleteDeadConditions=false,
constTargetLibraryInfo*TLI=nullptr,
DomTreeUpdater*DTU=nullptr);

//===----------------------------------------------------------------------===//
//Localdeadcodeelimination.
//

///Returntrueiftheresultproducedbytheinstructionisnotused,andthe
///instructionwillreturn.Certainside-effectinginstructionsarealso
///considereddeadiftherearenousesoftheinstruction.
boolisInstructionTriviallyDead(Instruction*I,
constTargetLibraryInfo*TLI=nullptr);

///Returntrueiftheresultproducedbytheinstructionwouldhavenoside
///effectsifitwasnotused.Thisisequivalenttocheckingwhether
///isInstructionTriviallyDeadwouldbetrueiftheusecountwas0.
boolwouldInstructionBeTriviallyDead(constInstruction*I,
constTargetLibraryInfo*TLI=nullptr);

///Returntrueiftheresultproducedbytheinstructionhasnosideeffectson
///anypathsotherthanwhereitisused.Thisislessconservativethan
///wouldInstructionBeTriviallyDeadwhichisbasedontheassumption
///thattheusecountwillbe0.AnexampleusageofthisAPIisfor
///identifyinginstructionsthatcanbesunkdowntouse(s).
boolwouldInstructionBeTriviallyDeadOnUnusedPaths(
Instruction*I,constTargetLibraryInfo*TLI=nullptr);

///Ifthespecifiedvalueisatriviallydeadinstruction,deleteit.
///Ifthatmakesanyofitsoperandstriviallydead,deletethemtoo,
///recursively.Returntrueifanyinstructionsweredeleted.
boolRecursivelyDeleteTriviallyDeadInstructions(
Value*V,constTargetLibraryInfo*TLI=nullptr,
MemorySSAUpdater*MSSAU=nullptr,
std::function<void(Value*)>AboutToDeleteCallback=
std::function<void(Value*)>());

///Deletealloftheinstructionsin`DeadInsts`,andallotherinstructions
///thatdeletingtheseinturncausestobetriviallydead.
///
///Theinitialinstructionsintheprovidedvectormustallhaveemptyuse
///listsandsatisfy`isInstructionTriviallyDead`.
///
///`DeadInsts`willbeusedasscratchstorageforthisroutineandwillbe
///emptyafterward.
voidRecursivelyDeleteTriviallyDeadInstructions(
SmallVectorImpl<WeakTrackingVH>&DeadInsts,
constTargetLibraryInfo*TLI=nullptr,MemorySSAUpdater*MSSAU=nullptr,
std::function<void(Value*)>AboutToDeleteCallback=
std::function<void(Value*)>());

///SamefunctionalityasRecursivelyDeleteTriviallyDeadInstructions,butallow
///instructionsthatarenottriviallydead.Thesewillbeignored.
///Returnstrueifanychangesweremade,i.e.anyinstructionstriviallydead
///werefoundanddeleted.
boolRecursivelyDeleteTriviallyDeadInstructionsPermissive(
SmallVectorImpl<WeakTrackingVH>&DeadInsts,
constTargetLibraryInfo*TLI=nullptr,MemorySSAUpdater*MSSAU=nullptr,
std::function<void(Value*)>AboutToDeleteCallback=
std::function<void(Value*)>());

///IfthespecifiedvalueisaneffectivelydeadPHInode,duetobeinga
///def-usechainofsingle-usenodesthateitherformsacycleoristerminated
///byatriviallydeadinstruction,deleteit.Ifthatmakesanyofits
///operandstriviallydead,deletethemtoo,recursively.Returntrueifa
///changewasmade.
boolRecursivelyDeleteDeadPHINode(PHINode*PN,
constTargetLibraryInfo*TLI=nullptr,
MemorySSAUpdater*MSSAU=nullptr);

///Scanthespecifiedbasicblockandtrytosimplifyanyinstructionsinit
///andrecursivelydeletedeadinstructions.
///
///Thisreturnstrueifitchangedthecode,notethatitcandelete
///instructionsinotherblocksaswellinthisblock.
boolSimplifyInstructionsInBlock(BasicBlock*BB,
constTargetLibraryInfo*TLI=nullptr);

///ReplacealltheusesofanSSAvaluein@llvm.dbgintrinsicswith
///undef.Thisisusefulforsignalingthatavariable,e.g.hasbeen
///founddeadandhenceit'sunavailableatagivenprogrampoint.
///Returnstrueifthedbgvalueshavebeenchanged.
boolreplaceDbgUsesWithUndef(Instruction*I);

//===----------------------------------------------------------------------===//
//ControlFlowGraphRestructuring.
//

///BBisablockwithonepredecessoranditspredecessorisknowntohaveone
///successor(BB!).Eliminatetheedgebetweenthem,movingtheinstructionsin
///thepredecessorintoBB.Thisdeletesthepredecessorblock.
voidMergeBasicBlockIntoOnlyPred(BasicBlock*BB,DomTreeUpdater*DTU=nullptr);

///BBisknowntocontainanunconditionalbranch,andcontainsnoinstructions
///otherthanPHInodes,potentialdebugintrinsicsandthebranch.If
///possible,eliminateBBbyrewritingallthepredecessorstobranchtothe
///successorblockandreturntrue.Ifwecan'ttransform,returnfalse.
boolTryToSimplifyUncondBranchFromEmptyBlock(BasicBlock*BB,
DomTreeUpdater*DTU=nullptr);

///CheckforandeliminateduplicatePHInodesinthisblock.Thisdoesn'ttry
///tobecleveraboutPHInodeswhichdifferonlyintheorderoftheincoming
///values,butinstcombineordersthemsoitusuallywon'tmatter.
///
///ThisoverloadremovestheduplicatePHInodesdirectly.
boolEliminateDuplicatePHINodes(BasicBlock*BB);

///CheckforandeliminateduplicatePHInodesinthisblock.Thisdoesn'ttry
///tobecleveraboutPHInodeswhichdifferonlyintheorderoftheincoming
///values,butinstcombineordersthemsoitusuallywon'tmatter.
///
///ThisoverloadcollectsthePHInodestoberemovedintotheToRemoveset.
boolEliminateDuplicatePHINodes(BasicBlock*BB,
SmallPtrSetImpl<PHINode *>&ToRemove);

///ThisfunctionisusedtodosimplificationofaCFG.Forexample,it
///adjustsbranchestobranchestoeliminatetheextrahop,iteliminates
///unreachablebasicblocks,anddoesotherpeepholeoptimizationoftheCFG.
///Itreturnstrueifamodificationwasmade,possiblydeletingthebasic
///blockthatwaspointedto.LoopHeadersisanoptionalinputparameter
///providingthesetofloopheadersthatSimplifyCFGshouldnoteliminate.
externcl::opt<bool>RequireAndPreserveDomTree;
boolsimplifyCFG(BasicBlock*BB,constTargetTransformInfo&TTI,
DomTreeUpdater*DTU=nullptr,
constSimplifyCFGOptions&Options={},
ArrayRef<WeakVH>LoopHeaders={});

///ThisfunctionisusedtoflattenaCFG.Forexample,itusesparallel-and
///andparallel-ormodetocollapseif-conditionsandmergeif-regionswith
///identicalstatements.
boolFlattenCFG(BasicBlock*BB,AAResults*AA=nullptr);

///IfthisbasicblockisONLYasetccandabranch,andifapredecessor
///branchestousandoneofoursuccessors,foldthesetccintothe
///predecessoranduselogicaloperationstopicktherightdestination.
boolfoldBranchToCommonDest(BranchInst*BI,llvm::DomTreeUpdater*DTU=nullptr,
MemorySSAUpdater*MSSAU=nullptr,
constTargetTransformInfo*TTI=nullptr,
unsignedBonusInstThreshold=1);

///ThisfunctiontakesavirtualregistercomputedbyanInstructionand
///replacesitwithaslotinthestackframe,allocatedviaalloca.
///ThisallowstheCFGtobechangedaroundwithoutfearofinvalidatingthe
///SSAinformationforthevalue.Itreturnsthepointertotheallocainserted
///tocreateastackslotforX.
AllocaInst*DemoteRegToStack(Instruction&X,
boolVolatileLoads=false,
std::optional<BasicBlock::iterator>AllocaPoint=std::nullopt);

///Thisfunctiontakesavirtualregistercomputedbyaphinodeandreplaces
///itwithaslotinthestackframe,allocatedviaalloca.Thephinodeis
///deletedanditreturnsthepointertotheallocainserted.
AllocaInst*DemotePHIToStack(PHINode*P,std::optional<BasicBlock::iterator>AllocaPoint=std::nullopt);

///Ifthespecifiedpointerpointstoanobjectthatwecontrol,trytomodify
///theobject'salignmenttoPrefAlign.Returnsaminimumknownalignmentof
///thevalueaftertheoperation,whichmaybelowerthanPrefAlign.
///
///Increatingvaluealignmentisn'toftenpossiblethough.Ifalignmentis
///important,amorereliableapproachistosimplyalignallglobalvariables
///andallocationinstructionstotheirpreferredalignmentfromthebeginning.
AligntryEnforceAlignment(Value*V,AlignPrefAlign,constDataLayout&DL);

///Trytoensurethatthealignmentof\pVisatleast\pPrefAlignbytes.If
///theowningobjectcanbemodifiedandhasanalignmentlessthan\p
///PrefAlign,itwillbeincreasedand\pPrefAlignreturned.Ifthealignment
///cannotbeincreased,theknownalignmentofthevalueisreturned.
///
///Itisnotalwayspossibletomodifythealignmentoftheunderlyingobject,
///soifalignmentisimportant,amorereliableapproachistosimplyalign
///allglobalvariablesandallocationinstructionstotheirpreferred
///alignmentfromthebeginning.
AligngetOrEnforceKnownAlignment(Value*V,MaybeAlignPrefAlign,
constDataLayout&DL,
constInstruction*CxtI=nullptr,
AssumptionCache*AC=nullptr,
constDominatorTree*DT=nullptr);

///Trytoinferanalignmentforthespecifiedpointer.
inlineAligngetKnownAlignment(Value*V,constDataLayout&DL,
constInstruction*CxtI=nullptr,
AssumptionCache*AC=nullptr,
constDominatorTree*DT=nullptr){
returngetOrEnforceKnownAlignment(V,MaybeAlign(),DL,CxtI,AC,DT);
}

///Createacallthatmatchestheinvoke\pIIintermsofarguments,
///attributes,debuginformation,etc.Thecallisnotplacedinablockandit
///willnothaveaname.Theinvokeinstructionisnotremoved,norarethe
///usesreplacedbythenewcall.
CallInst*createCallMatchingInvoke(InvokeInst*II);

///Thisfunctionconvertsthespecifiedinvokeintoanormalcall.
CallInst*changeToCall(InvokeInst*II,DomTreeUpdater*DTU=nullptr);

///===---------------------------------------------------------------------===//
