///Createsandinsertsadbg_valuerecordintrinsicbeforeastore
///thathasanassociatedllvm.dbg.valueintrinsic.
voidInsertDebugValueAtStoreLoc(DbgVariableRecord*DVR,StoreInst*SI,
DIBuilder&Builder);

///Createsandinsertsanllvm.dbg.valueintrinsicbeforeastore
///thathasanassociatedllvm.dbg.valueintrinsic.
voidInsertDebugValueAtStoreLoc(DbgVariableIntrinsic*DII,StoreInst*SI,
DIBuilder&Builder);

///Insertsallvm.dbg.valueintrinsicbeforeastoretoanalloca'dvalue
///thathasanassociatedllvm.dbg.declareintrinsic.
voidConvertDebugDeclareToDebugValue(DbgVariableIntrinsic*DII,
StoreInst*SI,DIBuilder&Builder);
voidConvertDebugDeclareToDebugValue(DbgVariableRecord*DVR,StoreInst*SI,
DIBuilder&Builder);

///Insertsallvm.dbg.valueintrinsicbeforealoadofanalloca'dvalue
///thathasanassociatedllvm.dbg.declareintrinsic.
voidConvertDebugDeclareToDebugValue(DbgVariableIntrinsic*DII,
LoadInst*LI,DIBuilder&Builder);
voidConvertDebugDeclareToDebugValue(DbgVariableRecord*DVR,LoadInst*LI,
DIBuilder&Builder);

///Insertsallvm.dbg.valueintrinsicafteraphithathasanassociated
///llvm.dbg.declareintrinsic.
