PHINode*LI,DIBuilder&Builder);
voidConvertDebugDeclareToDebugValue(DbgVariableRecord*DVR,PHINode*LI,
DIBuilder&Builder);

///Lowersllvm.dbg.declareintrinsicsintoappropriatesetof
///llvm.dbg.valueintrinsics.
boolLowerDbgDeclare(Function&F);

///Propagatedbg.valueintrinsicsthroughthenewlyinsertedPHIs.
voidinsertDebugValuesForPHIs(BasicBlock*BB,
SmallVectorImpl<PHINode *>&InsertedPHIs);

///Replacesllvm.dbg.declareinstructionwhentheaddressit
///describesisreplacedwithanewvalue.IfDerefistrue,an
///additionalDW_OP_derefisprependedtotheexpression.IfOffset
///isnon-zero,aconstantdisplacementisaddedtotheexpression
///(betweentheoptionalDerefoperations).Offsetcanbenegative.
boolreplaceDbgDeclare(Value*Address,Value*NewAddress,DIBuilder&Builder,
uint8_tDIExprFlags,intOffset);

///Replacesmultiplellvm.dbg.valueinstructionswhentheallocaitdescribes
///isreplacedwithanewvalue.IfOffsetisnon-zero,aconstantdisplacement
///isaddedtotheexpression(afterthemandatoryDeref).Offsetcanbe
///negative.Newllvm.dbg.valueinstructionsareinsertedatthelocationsof
///theinstructionstheyreplace.
voidreplaceDbgValueForAlloca(AllocaInst*AI,Value*NewAllocaAddress,
DIBuilder&Builder,intOffset=0);

///Assumingtheinstruction\pIisgoingtobedeleted,attempttosalvage
///debugusersof\pIbywritingtheeffectof\pIinaDIExpression.Ifit
///cannotbesalvagedchangesitsdebugusestoundef.
voidsalvageDebugInfo(Instruction&I);

///ImplementationofsalvageDebugInfo,applyingonlytoinstructionsin
///\pInsns,ratherthanalldebugusersfromfindDbgUsers(\pI).
///Markundefifsalvagingcannotbecompleted.
voidsalvageDebugInfoForDbgValues(Instruction&I,
ArrayRef<DbgVariableIntrinsic *>Insns,
ArrayRef<DbgVariableRecord *>DPInsns);

///Givenaninstruction\pIandDIExpression\pDIExproperatingon
///it,appendtheeffectsof\pItotheDIExpressionoperandlist
///\pOps,orreturn\pnullptrifitcannotbesalvaged.
///\pCurrentLocOpsisthenumberofSSAvaluesreferencedbythe
///incoming\pOps.\returnthefirstnon-constantoperand
///implicitlyreferredtobyOps.If\pIreferencesmorethanone
///non-constantoperand,anyadditionaloperandsareaddedto
///\pAdditionalValues.
///
///\example
////
///I=add%a,i321
///
///Return=%a
///Ops=llvm::dwarf::DW_OP_lit1llvm::dwarf::DW_OP_add
///
///I=add%a,%b
///
///Return=%a
///Ops=llvm::dwarf::DW_OP_LLVM_arg0llvm::dwarf::DW_OP_add
///AdditionalValues=%b
Value*salvageDebugInfoImpl(Instruction&I,uint64_tCurrentLocOps,
SmallVectorImpl<uint64_t>&Ops,
SmallVectorImpl<Value *>&AdditionalValues);

///Pointdebugusersof\pFromto\pToorsalvagethem.Usethisfunction
///onlywhenreplacingallusesof\pFromwith\pTo,withaguaranteethat
///\pFromisgoingtobedeleted.
///
///Followtheserulestopreventuse-before-defof\pTo:
///.If\pToisalinkedInstruction,set\pDomPointto\pTo.
///.If\pToisanunlinkedInstruction,set\pDomPointtotheInstruction
///\pTowillbeinsertedafter.
///.If\pToisnotanInstruction(e.gaConstant),thechoiceof
///\pDomPointisarbitrary.Pick\pFromforsimplicity.
///
///Ifadebugusercannotbepreservedwithoutreorderingvariableupdatesor
///introducingause-before-def,itiseithersalvaged(\refsalvageDebugInfo)
///ordeleted.Returnstrueifanydebuguserswereupdated.
boolreplaceAllDbgUsesWith(Instruction&From,Value&To,Instruction&DomPoint,
DominatorTree&DT);

///Ifaterminatorinanunreachablebasicblockhasanoperandoftype
///Instruction,transformitintopoison.Returntrueifanyoperands
///arechangedtopoison.OriginalValuespriortobeingchangedtopoison
///arereturnedin\pPoisonedValues.
boolhandleUnreachableTerminator(Instruction*I,
SmallVectorImpl<Value *>&PoisonedValues);

///Removeallinstructionsfromabasicblockotherthanitsterminator
///andanypresentEHpadinstructions.Returnsapairwherethefirstelement
///isthenumberofinstructions(excludingdebuginfointrinsics)thathave
///beenremoved,andthesecondelementisthenumberofdebuginfointrinsics
///thathavebeenremoved.
std::pair<unsigned,unsigned>
removeAllNonTerminatorAndEHPadInstructions(BasicBlock*BB);

///Insertanunreachableinstructionbeforethespecified
///instruction,makingitandtherestofthecodeintheblockdead.
unsignedchangeToUnreachable(Instruction*I,boolPreserveLCSSA=false,
DomTreeUpdater*DTU=nullptr,
MemorySSAUpdater*MSSAU=nullptr);

///ConverttheCallInsttoInvokeInstwiththespecifiedunwindedgebasic
