///InvokeInstisaterminatorinstruction.Returnsthenewlysplitbasic
///block.
BasicBlock*changeToInvokeAndSplitBasicBlock(CallInst*CI,
BasicBlock*UnwindEdge,
DomTreeUpdater*DTU=nullptr);

///Replace'BB'sterminatorwithonethatdoesnothaveanunwindsuccessor
///block.Rewrites`invoke`to`call`,etc.UpdatesanyPHIsinunwind
///successor.Returnstheinstructionthatreplacedtheoriginalterminator,
///whichmightbeacallincasetheoriginalterminatorwasaninvoke.
///
///\paramBBBlockwhoseterminatorwillbereplaced.Itsterminatormust
///haveanunwindsuccessor.
Instruction*removeUnwindEdge(BasicBlock*BB,DomTreeUpdater*DTU=nullptr);

///Removeallblocksthatcannotbereachedfromthefunction'sentry.
///
///Returnstrueifanybasicblockwasremoved.
boolremoveUnreachableBlocks(Function&F,DomTreeUpdater*DTU=nullptr,
MemorySSAUpdater*MSSAU=nullptr);

///CombinethemetadataoftwoinstructionssothatKcanreplaceJ.This
///specificallyhandlesthecaseofCSE-liketransformations.Some
///metadatacanonlybekeptifKdominatesJ.Forthistobecorrect,
///Kcannotbehoisted.
///
///Unknownmetadataisremoved.
voidcombineMetadataForCSE(Instruction*K,constInstruction*J,
boolDoesKMove);

///Combinemetadataoftwoinstructions,whereinstructionJisamemory
///accessthathasbeenmergedintoK.Thiswillintersectalias-analysis
