voidcombineAAMetadata(Instruction*K,constInstruction*J);

///Copythemetadatafromthesourceinstructiontothedestination(the
///replacementforthesourceinstruction).
voidcopyMetadataForLoad(LoadInst&Dest,constLoadInst&Source);

///Patchthereplacementsothatitisnotmorerestrictivethanthevalue
///beingreplaced.Itassumesthatthereplacementdoesnotgetmovedfrom
///itsoriginalposition.
voidpatchReplacementInstruction(Instruction*I,Value*Repl);

//Replaceeachuseof'From'with'To',ifthatusedoesnotbelongtobasic
//blockwhere'From'isdefined.Returnsthenumberofreplacementsmade.
unsignedreplaceNonLocalUsesWith(Instruction*From,Value*To);

///Replaceeachuseof'From'with'To'ifthatuseisdominatedby
///thegivenedge.Returnsthenumberofreplacementsmade.
unsignedreplaceDominatedUsesWith(Value*From,Value*To,DominatorTree&DT,
constBasicBlockEdge&Edge);
///Replaceeachuseof'From'with'To'ifthatuseisdominatedby
///theendofthegivenBasicBlock.Returnsthenumberofreplacementsmade.
unsignedreplaceDominatedUsesWith(Value*From,Value*To,DominatorTree&DT,
constBasicBlock*BB);
///Replaceeachuseof'From'with'To'ifthatuseisdominatedby
///thegivenedgeandthecallbackShouldReplacereturnstrue.Returnsthe
///numberofreplacementsmade.
unsignedreplaceDominatedUsesWithIf(
Value*From,Value*To,DominatorTree&DT,constBasicBlockEdge&Edge,
function_ref<bool(constUse&U,constValue*To)>ShouldReplace);
///Replaceeachuseof'From'with'To'ifthatuseisdominatedby
///theendofthegivenBasicBlockandthecallbackShouldReplacereturnstrue.
///Returnsthenumberofreplacementsmade.
unsignedreplaceDominatedUsesWithIf(
Value*From,Value*To,DominatorTree&DT,constBasicBlock*BB,
function_ref<bool(constUse&U,constValue*To)>ShouldReplace);

///Returntrueifthiscallcallsagcleaffunction.
///
///Aleaffunctionisafunctionthatdoesnotsafepointthethreadduringits
///execution.Duringacallorinvoketosuchafunction,thecallersstack
