///Trytomatchabswaporbitreverseidiom.
///
///Ifanidiomismatched,anintrinsiccallisinsertedbefore\cI.Anyadded
///instructionsarereturnedin\cInsertedInsts.Theywillallhavebeenadded
///toabasicblock.
///
///Abitreverseidiomnormallyrequiresaround2*BWnodestobesearched(where
///BWisthebitwidthoftheintegertype).Abswapidiomrequiresanywhereup
///toBW/4nodestobesearched,soissignificantlyfaster.
///
///Thisfunctionreturnstrueonasuccessfulmatchorfalseotherwise.
boolrecognizeBSwapOrBitReverseIdiom(
Instruction*I,boolMatchBSwaps,boolMatchBitReversals,
SmallVectorImpl<Instruction *>&InsertedInsts);

